import csv


def parse_price(s: str) -> float:
    return float(s.replace(",", "."))


def answer() -> int:
    catalog = list(csv.DictReader(open("/app/dataset/product_catalog.csv")))
    price = {r["product_id"]: parse_price(r["unit_price"]) for r in catalog}
    ean_to_pid = {r["ean_code"]: r["product_id"] for r in catalog}

    dispatches = list(csv.DictReader(open("/app/dataset/warehouse_dispatches.csv")))

    # Bulk dispatch of Frozen/Meat items at an anomalous 03:17 AM timestamp on
    # 2023-07-18, coinciding exactly with a temperature excursion above
    # max_safe_temp_c in the frozen and meat zones (per temperature_logs.csv).
    # This is the spoilage disposal event and must be excluded from revenue.
    disposal_timestamp = "2023-07-18 03:17:00"

    seen = set()
    revenue = 0.0
    for r in dispatches:
        if r["timestamp"] == disposal_timestamp:
            continue

        pid = r["product_id"]
        if pid not in price:
            pid = ean_to_pid.get(pid, pid)  # one row logs EAN code instead of product_id

        # 2023-07-10 through 2023-07-14 have every dispatch row duplicated
        # (identical timestamp/product/quantity/weight) due to a data export
        # glitch; count each physical dispatch once.
        key = (r["timestamp"], pid, r["quantity"], r["total_weight_kg"])
        if key in seen:
            continue
        seen.add(key)

        revenue += float(r["quantity"]) * price[pid]

    return round(revenue)


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

